def is_multiply_prime(a):
    factors = []

    # Check for prime factors up to the square root of 'a'
    for i in range(2, int(a**0.5) + 1):
        if a % i == 0:
            if is_prime(i):
                factors.append(i)
            while a % i == 0:
                a //= i

    # If there's any remaining factor greater than the square root of 'a'
    if a > 1:
