def select_words(s, n):
    def is_consonant(c):
        return c.lower() in 'bcdfghjklmnpqrstvwxyz'

    words = s.split()
    result = []

    for word in words:
        if sum(is_consonant(char) for char in word) == n:
            result.append(word)

    return result
```

